  .accordion-item summary {
    padding: 18px;
  }

  .accordion-copy {
    padding-inline: 18px;
  }
}

@media (max-width: 767px) {
  html {
    scroll-padding-top: 5rem;
  }

  .site-nav {
    min-height: 64px;
    padding: 10px 18px;
  }

  .wordmark {
    font-size: 17px;
  }

  .nav-hire {
    min-height: 44px;
    padding: 8px 16px;
    font-size: 16px;
  }

  .hero {
    min-height: auto;
    padding: 80px 18px 0;
  }

  .hero h1 {
    margin-top: 22px;
    font-size: clamp(2.65rem, 13vw, 3.25rem);
    line-height: 0.98;
  }

  .hero-actions {
    width: 100%;
    margin-top: 30px;
  }

  .hero-actions .button {
    flex: 1;
    padding-inline: 14px;
  }

  .cube-stage {
    width: calc(100% + 36px);
    height: 360px;
    margin-top: 48px;
    border-radius: 0;
  }

  .chapter {
    padding: 112px 18px;
  }

  .section-heading {
    margin-bottom: 42px;
  }

  .section-heading h2 {
    font-size: clamp(2.7rem, 13vw, 4rem);
  }

  .project-bento {
    width: calc(100% + 36px);
    margin-left: -18px;
    border-radius: 0;
  }

  .project-card {
    min-height: 580px;
  }

  .field-statement,
  .contact-section {
    width: 100%;
    border-radius: 0;
  }

  .field-statement {
    padding: 88px 24px;
  }

  .field-statement h2 {
    font-size: clamp(2.65rem, 12vw, 4rem);
  }

  .field-copy {
    margin-top: 42px;
    font-size: 19px;
  }

  .project-accordion {
    display: block;
    min-height: 0;
    margin-bottom: 112px;
    border-radius: 0;
  }

  .accordion-item {
    border-right: 0;
    border-bottom: 1px solid var(--ink);
  }

  .accordion-item:last-child {
    border-bottom: 0;
  }

  .accordion-item summary {
    min-height: 136px;
  }

  .stack-card {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(330px, 52svh);
    min-height: 75svh;
    margin-bottom: 80px;
    border-radius: 0;
  }

  .stack-copy {
    padding: 34px 24px;
  }

  .stack-copy h3 {
    font-size: clamp(2.5rem, 13vw, 4rem);
  }

  .stack-media {
    margin: 0 14px 14px;
    border-radius: 12px;
  }

  .contact-section {
    min-height: 76svh;
    margin: 24px 0 112px;
    padding: 72px 24px;
  }

  .contact-section h2 {
    font-size: clamp(3.1rem, 15vw, 5rem);
  }

  .contact-section .button {
    width: 100%;
  }

  .site-footer {
    grid-template-columns: 1fr;
    padding: 64px 24px;
  }

  .site-footer nav {
    justify-content: flex-start;
  }
}

@media (max-width: 420px) {
  .wordmark {
    max-width: 72px;
    line-height: 1;
  }

  .mobile-nav summary {
    padding-inline: 6px;
  }

  .nav-hire {
    padding-inline: 13px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .marquee-track {
    transform: none;
  }
}

