--- HEAD CSS key areas ---
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(100%, 1440px);
  min-height: calc(100svh - 72px);
  margin: 0 auto;
  padding: clamp(72px, 9vw, 128px) 32px 0;
  text-align: center;
}

.eyebrow {
  margin: 0;
  font-family: var(--font-geist-mono), monospace;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.hero h1 {
  max-width: 72rem;
  margin: 28px auto 0;
  font-size: clamp(3.25rem, 7vw, 6.5rem);
  font-weight: 340;
  line-height: 0.96;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.hero-actions {
  display: flex;
  gap: 12px;
  margin-top: 36px;
}

.cube-stage {
  position: relative;
  width: min(100%, 1120px);
  height: clamp(340px, 48vw, 610px);
  margin-top: 48px;
  overflow: hidden;
  background: var(--surface-soft);
  border-radius: 24px 24px 0 0;
  isolation: isolate;
}

.cube-stage > div {
  width: 100% !important;
  height: 100% !important;
}

.cube-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: var(--block-cream);
}

.cube-fallback span {
  .accordion-copy {
    padding-inline: 18px;
  }
}

@media (max-width: 767px) {
  html {
    scroll-padding-top: 5rem;
  }

  .site-nav {
    min-height: 64px;
    padding: 10px 18px;
  }

  .wordmark {
    font-size: 17px;
  }

  .nav-hire {
    min-height: 44px;
    padding: 8px 16px;
    font-size: 16px;
  }

  .hero {
    min-height: auto;
    padding: 80px 18px 0;
  }

  .hero h1 {
    margin-top: 22px;
    font-size: clamp(2.65rem, 13vw, 3.25rem);
    line-height: 0.98;
  }

  .hero-actions {
    width: 100%;
    margin-top: 30px;
  }

  .hero-actions .button {
    flex: 1;
    padding-inline: 14px;
  }

  .cube-stage {
    width: calc(100% + 36px);
    height: 360px;
    margin-top: 48px;
    border-radius: 0;
  }

  .chapter {
    padding: 112px 18px;
  }

  .section-heading {
    margin-bottom: 42px;
  }

  .section-heading h2 {
    font-size: clamp(2.7rem, 13vw, 4rem);
  }

  .project-bento {
    width: calc(100% + 36px);
    margin-left: -18px;
    border-radius: 0;
  }

  .project-card {
    min-height: 580px;
  }

  .field-statement,
    grid-template-columns: 1fr;
    padding: 64px 24px;
  }

  .site-footer nav {
    justify-content: flex-start;
  }
}

@media (max-width: 420px) {
  .wordmark {
    max-width: 72px;
    line-height: 1;
  }

  .mobile-nav summary {
    padding-inline: 6px;
  }

  .nav-hire {
    padding-inline: 13px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .marquee-track {
    transform: none;
  }
}

